const $ = selector => document.querySelector(selector);
const app = $('#app'), modal = $('#modal');
const state = { user:null,csrf:null,data:null,tab:'dashboard',search:'',filter:'active',vacationFilter:'all',payroll:null,report:null,reportYear:null,reportDate:null,preview:null };
const icons = {
  dashboard:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
  people:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87"/><circle cx="9" cy="7" r="4"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/>',
  calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18m-13 5h2m4 0h2"/>',
  holiday:'<path d="M12 3v2m0 14v2M3 12h2m14 0h2M5.6 5.6 7 7m10 10 1.4 1.4M5.6 18.4 7 17M17 7l1.4-1.4"/><circle cx="12" cy="12" r="4"/>',
  wallet:'<path d="M20 8V5a2 2 0 0 0-2-2H5a3 3 0 0 0 0 6h15v12H5a3 3 0 0 1-3-3V6"/><path d="M20 12h-5v5h5m-3-2.5h.01"/>',
  report:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zM14 2v6h6M8 17v-3m4 3v-5m4 5v-2"/>',
  settings:'<path d="m12 3 2 3 3-.3.3 3 3 2-3 2-.3 3-3-.3-2 3-2-3-3 .3-.3-3-3-2 3-2 .3-3 3 .3z"/><circle cx="12" cy="11" r="3"/>',
  plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',
  logout:'<path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4m7 14 5-5-5-5M21 12H9"/>',
  search:'<circle cx="10.5" cy="10.5" r="7.5"/><path d="m16 16 5 5"/>',edit:'<path d="m16 3 5 5-12 12-6 1 1-6zM14 5l5 5"/>',
  close:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<path d="m5 12 4 4L19 6"/>',
  download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v4h16v-4"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',
  eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12"/><circle cx="12" cy="12" r="3"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-6"/>',
  trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
  refresh:'<path d="M20 7v5h-5M4 17v-5h5M6 6a8 8 0 0 1 13 2M5 16a8 8 0 0 0 13 2"/>',warning:'<path d="m12 3 10 18H2zM12 9v5m0 3h.01"/>',
  lock:'<rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',leaf:'<path d="M20 3c0 12-5 17-10 17a7 7 0 0 1-7-7C3 8 8 3 20 3zM5 19 15 9"/>',
};
const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name] || icons.report}</svg>`;
const escape = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = cents => new Intl.NumberFormat('es-CR',{style:'currency',currency:'CRC',minimumFractionDigits:2}).format(Number(cents || 0)/100);
const days = value => new Intl.NumberFormat('es-CR',{minimumFractionDigits:0,maximumFractionDigits:2}).format(Number(value || 0));
const civil = (value,options={day:'numeric',month:'short',year:'numeric'}) => value ? new Intl.DateTimeFormat('es-CR',{...options,timeZone:'UTC'}).format(new Date(`${value}T12:00:00Z`)) : '—';
const timestamp = value => new Intl.DateTimeFormat('es-CR',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'America/Costa_Rica'}).format(new Date(value));
const initials = name => String(name).split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const person = e => `<div class="person"><span class="avatar">${escape(initials(e.full_name))}</span><div><strong>${escape(e.full_name)}</strong><small>${escape(e.position || e.code)}</small></div></div>`;
const btn = (label,action,ico,variant='',extra='') => `<button class="btn ${variant}" data-action="${action}" ${extra}>${ico?icon(ico):''}${escape(label)}</button>`;
const tag = (label,cls='') => `<span class="tag ${cls}">${escape(label)}</span>`;
let fieldCount=0;
function field(label,name,value='',type='text',extra='',help='') {
  const id=`field-${++fieldCount}`;
  return `<div class="field ${extra.includes('data-full')?'full':''}"><label for="${id}">${escape(label)}</label><input id="${id}" name="${name}" type="${type}" value="${escape(value)}" ${extra}>${help?`<small>${escape(help)}</small>`:''}</div>`;
}
function select(label,name,options,value,extra='') {
  const id=`field-${++fieldCount}`;
  return `<div class="field"><label for="${id}">${escape(label)}</label><select id="${id}" name="${name}" ${extra}>${options.map(([key,label])=>`<option value="${escape(key)}" ${String(key)===String(value)?'selected':''}>${escape(label)}</option>`).join('')}</select></div>`;
}
function textarea(label,name,value='',help='') {
  const id=`field-${++fieldCount}`;
  return `<div class="field full"><label for="${id}">${escape(label)}</label><textarea id="${id}" name="${name}" maxlength="2000">${escape(value)}</textarea>${help?`<small>${escape(help)}</small>`:''}</div>`;
}
const empty = (title,description,action='',ico='people',compact=false) => `<div class="empty ${compact?'compact':''}"><div class="empty-icon">${icon(ico)}</div><strong>${escape(title)}</strong><p>${escape(description)}</p>${action}</div>`;
function toast(message,error=false) {
  const el=$('#toast');el.textContent=message;el.classList.toggle('error',error);el.hidden=false;
  clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,6000);
}
async function api(path,{method='GET',body}={}) {
  const response=await fetch(`/api${path}`,{method,headers:{'Content-Type':'application/json',...(state.csrf?{'X-CSRF-Token':state.csrf}:{})},body:body===undefined?undefined:JSON.stringify(body)});
  const result=await response.json();
  if (!response.ok) {
    if (response.status===401 && !['/auth/login','/auth/status'].includes(path)) {state.user=null;modal.close();renderAuth(true);}
    const error=new Error(result.error || 'No se pudo completar la operación.');Object.assign(error,{code:result.code,details:result.details});throw error;
  }
  return result;
}
async function load() {state.data=await api('/bootstrap');state.report=null;if(state.tab==='reports')state.report=await api(`/reports/vacations?year=${state.reportYear||state.data.today.slice(0,4)}&as_of=${state.reportDate||state.data.today}`);render();}
function renderAuth(initialized) {
  app.innerHTML=`<div class="auth-layout"><aside class="auth-story"><div class="brand"><img src="/assets/circuito-cinco-logo.png" alt="Circuito Cinco" width="1495" height="381"><small>RECURSOS HUMANOS</small></div><div class="auth-story-content"><div class="eyebrow">UN ESPACIO PARA TU EQUIPO</div><h1>Las personas,<br>en el centro.<br><em>Todo lo demás,<br>en orden.</em></h1><p>Un lugar para administrar tu equipo, sus vacaciones y cada quincena, con claridad y tranquilidad.</p><div class="auth-features"><span>${icon('people')}Personal</span><span>${icon('calendar')}Vacaciones</span><span>${icon('wallet')}Nómina</span></div></div><div class="auth-footer">Hecho para tu empresa · Costa Rica</div></aside><main class="auth-right"><div class="auth-card"><div class="auth-mobile-brand"><div class="brand"><img src="/assets/circuito-cinco-logo.png" alt="Circuito Cinco" width="1495" height="381"><small>RECURSOS HUMANOS</small></div></div><div class="eyebrow">${initialized?'BIENVENIDO A CIRCUITO CINCO':'EMPECEMOS POR LO ESENCIAL'}</div><h2>${initialized?'Tu equipo te espera.':'Crea tu espacio de trabajo.'}</h2><p>${initialized?'Ingresa con tu cuenta de administrador para continuar.':'Registra la empresa y tu primera cuenta de administrador. Luego podrás incorporar a los trabajadores.'}</p><form data-form="${initialized?'login':'setup'}">${!initialized?field('Nombre de la empresa','company_name','','text','required maxlength="200"')+field('Tu nombre','name','','text','required maxlength="200"'):''}${field('Correo electrónico','email','','email','required autocomplete="username" maxlength="254"')}${field(initialized?'Contraseña':'Contraseña de administrador','password','','password',`required ${initialized?'':'minlength="12"'} maxlength="128" autocomplete="${initialized?'current-password':'new-password'}"`,initialized?'':'Utiliza al menos 12 caracteres.')}${!initialized?field('Confirma tu contraseña','password_confirm','','password','required minlength="12" maxlength="128" autocomplete="new-password"'):''}<div class="form-error" role="alert"></div><button type="submit" class="btn primary">${initialized?'Ingresar':'Crear empresa y administrador'}${icon('arrow')}</button></form><p class="auth-footnote">Acceso exclusivo para administradores de la empresa.</p></div></main></div>`;
}
const tabs=[['dashboard','Resumen','dashboard'],['employees','Empleados','people'],['vacations','Vacaciones','calendar'],['holidays','Feriados','holiday'],['payroll','Nómina','wallet'],['reports','Reportes','report'],['settings','Configuración','settings']];
function render() {
  if (!state.data || !state.user) return;
  const active=state.data.employees.filter(e=>e.active).length;
  app.innerHTML=`<aside class="sidebar"><div class="brand"><img src="/assets/circuito-cinco-logo.png" alt="Circuito Cinco" width="1495" height="381"><small>RECURSOS HUMANOS</small></div><div class="nav-label">Espacio de trabajo</div><nav aria-label="Navegación principal">${tabs.slice(0,6).map(([id,label,ico])=>`<button data-action="navigate" data-tab="${id}" class="nav-item ${state.tab===id?'active':''}" ${state.tab===id?'aria-current="page"':''}>${icon(ico)}${label}${id==='employees'?`<span class="nav-count">${active}</span>`:''}</button>`).join('')}</nav><div class="nav-label">Administración</div><button data-action="navigate" data-tab="settings" class="nav-item ${state.tab==='settings'?'active':''}">${icon('settings')}Configuración</button><div class="sidebar-bottom"><div class="local-indicator"><span class="dot"></span>Espacio de la empresa</div><p class="sidebar-note">${escape(state.data.company.name)}</p></div></aside><main class="main"><header class="topbar"><div class="button-row"><button class="icon-button mobile-menu" data-action="menu" aria-label="Abrir menú">${icon('menu')}</button><img class="mobile-header-logo" src="/assets/circuito-cinco-logo.png" alt="Circuito Cinco" width="1495" height="381"><div class="breadcrumb">${escape(state.data.company.name)} &nbsp; / &nbsp; <strong>${tabs.find(t=>t[0]===state.tab)[1]}</strong></div></div><div class="top-actions"><span class="top-date">${civil(state.data.today,{weekday:'long',day:'numeric',month:'long'})}</span><div class="profile"><span class="avatar">${escape(initials(state.user.name))}</span><div><div class="profile-name">${escape(state.user.name)}</div><small>Administrador</small></div></div><button class="icon-button" data-action="logout" title="Cerrar sesión" aria-label="Cerrar sesión">${icon('logout')}</button></div></header><div class="content" id="page-content">${page()}</div></main>`;
}
function heading(title,description,action='',eyebrow='ADMINISTRACIÓN DE PERSONAL') {return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${escape(title)}</h1><p>${escape(description)}</p></div>${action}</div>`;}
function stat(label,value,description,ico,cls='') {return `<div class="stat"><div class="stat-top"><span>${escape(label)}</span><span class="stat-icon">${icon(ico)}</span></div><div class="stat-value ${cls}">${escape(value)}</div><div class="stat-footer">${escape(description)}</div></div>`;}
function activityList(limit=5) {
  const actions={crear:'Registro creado',editar:'Información actualizada',aprobar:'Vacaciones aprobadas',cancelar:'Vacaciones canceladas',cerrar:'Nómina cerrada',ingresar:'Inicio de sesión',enviar_colilla:'Colilla enviada',cambiar_contraseña:'Contraseña actualizada',restablecer_contraseña:'Contraseña restablecida',cambiar_estado:'Estado de cuenta actualizado',actualizar_plantilla:'Plantilla actualizada',retirar_del_borrador:'Trabajador retirado del borrador'};
  const rows=state.data.audit.slice(0,limit);
  return rows.length?rows.map(a=>`<div class="activity"><span class="activity-icon">${icon(a.entity==='vacaciones'?'calendar':a.entity.startsWith('nomina')?'wallet':a.entity==='cuenta'?'shield':'edit')}</span><div><p>${escape(actions[a.action]||a.action.replaceAll('_',' '))} <span class="muted">· ${escape(a.entity.replaceAll('_',' '))}</span></p><small>${escape(a.actor_name||'Sistema')} · ${timestamp(a.created_at)}</small></div></div>`).join(''):empty('Sin movimientos','Los cambios de tu equipo aparecerán aquí.','','clock',true);
}
function dashboard() {
  const d=state.data,employees=d.employees.filter(e=>e.active),negative=employees.filter(e=>e.vacation.available<0),salary=employees.reduce((s,e)=>s+Number(e.monthly_salary_cents),0);
  const upcoming=d.vacations.filter(v=>v.status==='approved'&&v.end_date>=d.today).sort((a,b)=>a.start_date.localeCompare(b.start_date)).slice(0,4);
  const latest=d.periods[0];
  const firstName=state.user.name.split(' ')[0];
  return `${heading(`Todo tu equipo, en un vistazo.`,`Bienvenido, ${firstName}. Aquí tienes lo que necesita tu atención.`,btn('Nuevo empleado','employee-new','plus','primary'),'TU EMPRESA, AL DÍA')}<div class="welcome-banner"><div><h2>${employees.length?'Un equipo bien organizado empieza aquí.':'Dale la bienvenida a tu primer trabajador.'}</h2><p>${employees.length?'Gestiona el personal, planifica sus días de descanso y prepara cada pago desde un mismo lugar.':'Crea los perfiles de tu equipo y registra los días históricos de vacaciones. Circuito se encargará de llevar la cuenta desde ahí.'}</p></div>${employees.length?'<div class="banner-icon">'+icon('leaf')+'</div>':btn('Registrar empleado','employee-new','arrow','primary')}</div><div class="stats">${stat('Empleados activos',employees.length,'Personas que forman parte del equipo','people')}${stat('Vacaciones reservadas',days(employees.reduce((s,e)=>s+e.vacation.reserved,0))+' días','Días aprobados pendientes de disfrutar','calendar')}${stat('Salarios por quincena',money(employees.reduce((s,e)=>s+Math.round(Number(e.monthly_salary_cents)/2),0)),'Salarios base · sin comisiones ni rebajos','wallet','money')}${stat('Saldos por revisar',negative.length,'Trabajadores con vacaciones disponibles negativas','warning',negative.length?'negative':'')}</div>${negative.length?`<div class="notice warning"><strong>${negative.length} ${negative.length===1?'trabajador tiene':'trabajadores tienen'} un saldo de vacaciones negativo.</strong> Revisa los saldos antes de aprobar nuevas fechas. ${btn('Ver saldos','navigate','arrow','small','data-tab="vacations"')}</div>`:''}<div class="grid-two"><section class="panel"><div class="panel-header"><div><h2>Próximas vacaciones</h2><p>Descansos aprobados para tu equipo</p></div><button class="text-link" data-action="navigate" data-tab="vacations">Ver todas ${icon('arrow')}</button></div>${upcoming.length?`<div class="table-wrap"><table><thead><tr><th>Trabajador</th><th>Fechas</th><th>Días</th></tr></thead><tbody>${upcoming.map(v=>{const e=d.employees.find(e=>e.id===v.employee_id);return `<tr><td>${person(e)}</td><td><span class="no-wrap">${civil(v.start_date,{day:'numeric',month:'short'})} — ${civil(v.end_date,{day:'numeric',month:'short'})}</span><div class="figure-note">${v.start_date<=d.today?'En curso':'Programadas'}</div></td><td>${tag(days(v.days)+' días')}</td></tr>`;}).join('')}</tbody></table></div>`:empty('Sin vacaciones programadas','Cuando apruebes un descanso, verás aquí las próximas fechas.',btn('Registrar vacaciones','vacation-new','plus','small'),'calendar',true)}</section><section class="panel"><div class="panel-header"><div><h2>Resumen de nómina</h2><p>${latest?`${civil(latest.start_date,{day:'numeric',month:'long'})} al ${civil(latest.end_date,{day:'numeric',month:'long'})}`:'Prepara el primer periodo de pago'}</p></div>${latest?tag(latest.status==='closed'?'Cerrada':'Borrador',latest.status==='closed'?'':'amber'):icon('wallet')}</div><div class="panel-body"><div class="summary-row"><span class="muted">Trabajadores</span><strong>${latest?latest.employee_count:employees.length}</strong></div><div class="summary-row"><span class="muted">Base mensual del equipo</span><strong>${money(salary)}</strong></div><div class="summary-total"><span>${latest?'Neto del periodo':'Base quincenal'}</span><strong>${money(latest?latest.total_net_cents:employees.reduce((s,e)=>s+Math.round(Number(e.monthly_salary_cents)/2),0))}</strong></div><p class="figure-note">${latest?'Los importes corresponden al periodo guardado.':'Caja, renta y comisiones se ingresan por trabajador en cada quincena.'}</p>${btn(latest?'Revisar nómina':'Preparar nómina',latest?'payroll-open':'payroll-new','arrow','primary full-width',latest?`data-id="${latest.id}"`:'')}</div></section></div><div class="grid-two"><section class="panel"><div class="panel-header"><div><h2>El equipo</h2><p>Personas, saldos y datos en un solo lugar</p></div><button class="text-link" data-action="navigate" data-tab="employees">Ver equipo ${icon('arrow')}</button></div>${employees.length?`<div class="table-wrap"><table><thead><tr><th>Trabajador</th><th>Ingreso</th><th>Disponible</th><th></th></tr></thead><tbody>${employees.slice(0,4).map(e=>`<tr><td>${person(e)}</td><td>${civil(e.hire_date)}</td><td><span class="balance ${e.vacation.available<0?'negative':''}">${days(e.vacation.available)}</span> <span class="muted small">días</span></td><td><button class="icon-button" data-action="employee-view" data-id="${e.id}" aria-label="Ver perfil de ${escape(e.full_name)}">${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('Tu equipo empieza contigo','Registra los datos de cada trabajador para organizar vacaciones y pagos.','','people',true)}</section><section class="panel"><div class="panel-header"><div><h2>Actividad reciente</h2><p>Un historial de cada movimiento</p></div>${icon('clock')}</div><div class="panel-body">${activityList()}</div></section></div><div class="dashboard-shortcuts"><button class="shortcut" data-action="vacation-new">${icon('calendar')}<span><strong>Planificar un descanso</strong><small>Contar solo los días laborales</small></span></button><button class="shortcut" data-action="navigate" data-tab="holidays">${icon('holiday')}<span><strong>Organizar los feriados</strong><small>Mantener actualizado el calendario</small></span></button><button class="shortcut" data-action="navigate" data-tab="reports">${icon('report')}<span><strong>Consultar los saldos</strong><small>Vacaciones y movimientos del año</small></span></button></div><div class="footer-note"><span>Circuito Cinco · ${escape(d.company.name)}</span><span>Colones costarricenses · Calendario de Costa Rica</span></div>`;
}
function employeeRows() {
  const rows=state.data.employees.filter(e=>(state.filter==='all'||e.active===(state.filter==='active'))&&`${e.full_name} ${e.national_id} ${e.code} ${e.department}`.toLowerCase().includes(state.search.toLowerCase()));
  return rows.length?`<div class="table-wrap"><table><thead><tr><th>Trabajador</th><th>Cédula</th><th>Ingreso</th><th>Salario mensual</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${rows.map(e=>`<tr><td>${person(e)}</td><td>${escape(e.national_id)}</td><td class="no-wrap">${civil(e.hire_date)}</td><td class="no-wrap">${money(e.monthly_salary_cents)}</td><td>${tag(e.active?'Activo':'Inactivo',e.active?'':'gray')}</td><td><div class="button-row"><button class="icon-button" data-action="employee-view" data-id="${e.id}" aria-label="Ver perfil de ${escape(e.full_name)}">${icon('eye')}</button><button class="icon-button" data-action="employee-edit" data-id="${e.id}" aria-label="Editar ${escape(e.full_name)}">${icon('edit')}</button></div></td></tr>`).join('')}</tbody></table></div>`:empty(state.data.employees.length?'Sin resultados':'Cada persona cuenta',state.data.employees.length?'Prueba otro nombre, cédula o filtro.':'Registra tu equipo con sus datos, salario mensual y ajuste histórico de vacaciones.',state.data.employees.length?'':btn('Registrar empleado','employee-new','plus','primary'));
}
function employeesPage() {return `${heading('Tu equipo','Administra los perfiles y mantén los datos de cada trabajador al día.',btn('Nuevo empleado','employee-new','plus','primary'))}<section class="panel"><div class="toolbar"><div class="search">${icon('search')}<input id="employee-search" aria-label="Buscar empleados" placeholder="Buscar nombre, cédula o código…" value="${escape(state.search)}"></div><div class="button-row"><span class="small muted">${state.data.employees.length} perfiles</span><select id="employee-filter" aria-label="Estado de los empleados"><option value="active" ${state.filter==='active'?'selected':''}>Activos</option><option value="inactive" ${state.filter==='inactive'?'selected':''}>Inactivos</option><option value="all" ${state.filter==='all'?'selected':''}>Todos</option></select></div></div><div id="employee-table">${employeeRows()}</div></section>`;}
function vacationsPage() {
  const employees=state.data.employees.filter(e=>e.active);const requests=state.data.vacations.filter(v=>state.vacationFilter==='all'||v.status===state.vacationFilter);
  return `${heading('Tiempo para descansar','Los días se acumulan por mes completo. Cada 12 meses equivalen a 14 días.',btn('Registrar vacaciones','vacation-new','plus','primary'))}<div class="notice">Se descuentan únicamente días de lunes a viernes, excluyendo los feriados registrados. Se permiten medios días y adelantos con advertencia.</div><section class="panel"><div class="panel-header"><div><h2>Saldos de vacaciones</h2><p>Al ${civil(state.data.today)} · trabajadores activos</p></div>${btn('Reporte completo','navigate','report','small','data-tab="reports"')}</div>${employees.length?`<div class="table-wrap"><table><thead><tr><th>Trabajador</th><th>Acumulado</th><th>Histórico</th><th>Utilizado</th><th>Saldo actual</th><th>Reservado</th><th>Disponible</th><th></th></tr></thead><tbody>${employees.map(e=>`<tr><td>${person(e)}</td><td>${days(e.vacation.accrued)}</td><td>${days(e.vacation.historical)}</td><td>${days(e.vacation.used)}</td><td class="${e.vacation.balance<0?'negative':''}">${days(e.vacation.balance)}</td><td>${days(e.vacation.reserved)}</td><td><span class="balance ${e.vacation.available<0?'negative':''}">${days(e.vacation.available)}</span>${e.vacation.available<0?`<div class="figure-note negative">Saldo negativo</div>`:''}</td><td>${btn('Registrar','vacation-new','plus','small',`data-id="${e.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('Primero, tu equipo','Registra los empleados para comenzar a llevar sus vacaciones.',btn('Nuevo empleado','employee-new','plus','small'),'calendar')}</section><section class="panel spacer-top"><div class="toolbar"><div><strong>Movimientos de vacaciones</strong><div class="figure-note">Los movimientos cancelados se conservan en el historial.</div></div><select id="vacation-filter" aria-label="Estado de vacaciones"><option value="all">Todos</option><option value="approved" ${state.vacationFilter==='approved'?'selected':''}>Aprobados</option><option value="cancelled" ${state.vacationFilter==='cancelled'?'selected':''}>Cancelados</option></select></div>${requests.length?`<div class="table-wrap"><table><thead><tr><th>Trabajador</th><th>Desde</th><th>Hasta</th><th>Días</th><th>Estado</th><th>Detalle</th><th></th></tr></thead><tbody>${requests.map(v=>`<tr><td><strong>${escape(v.full_name)}</strong><div class="figure-note">${escape(v.code)}</div></td><td class="no-wrap">${civil(v.start_date)}</td><td class="no-wrap">${civil(v.end_date)}</td><td>${days(v.days)}</td><td>${tag(v.status==='cancelled'?'Cancelada':v.end_date<state.data.today?'Disfrutada':v.start_date<=state.data.today?'En curso':'Programada',v.status==='cancelled'?'gray':'')}</td><td class="small">${escape(v.status==='cancelled'?v.cancellation_reason:v.note||'—')}</td><td>${v.status==='approved'?btn('Cancelar','vacation-cancel','close','small danger',`data-id="${v.id}"`):''}</td></tr>`).join('')}</tbody></table></div>`:empty('Sin movimientos','Registra una fecha de descanso y revisa el conteo antes de aprobar.','','calendar',true)}</section>`;
}
function holidaysPage() {
  const rows=state.data.holidays;
  return `${heading('Un calendario bien cuidado','Agrega las fechas que tu empresa reconocerá como feriados.',btn('Agregar feriado','holiday-new','plus','primary'))}<div class="notice">Los feriados se registran con su fecha exacta. Agrega los de cada año antes de aprobar vacaciones. Si coinciden con un sábado o domingo, no se descuentan dos veces.</div><section class="panel"><div class="panel-header"><div><h2>Feriados registrados</h2><p>${rows.length} fechas en el calendario de la empresa</p></div>${icon('holiday')}</div>${rows.length?rows.map(h=>`<div class="holiday-card"><div class="holiday-date"><strong>${civil(h.day,{day:'numeric'})}</strong><small>${civil(h.day,{month:'short'})}</small></div><div class="holiday-info"><strong>${escape(h.name)}</strong><p>${civil(h.day,{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</p></div>${tag(h.day<state.data.today?'Pasado':'Próximo',h.day<state.data.today?'gray':'')}<button class="icon-button" data-action="holiday-delete" data-id="${h.id}" aria-label="Eliminar ${escape(h.name)}">${icon('trash')}</button></div>`).join(''):empty('El calendario está listo para empezar','Agrega los feriados correspondientes a tu empresa. No se precargan fechas para que puedas definir el calendario aplicable.',btn('Agregar primer feriado','holiday-new','plus','primary'),'holiday')}</section>`;
}
function periodLabel(p) {return `${civil(p.start_date,{month:'long',year:'numeric'})} · ${p.half===1?'Primera':'Segunda'} quincena`;}
function payslipActions(item,period) {
  const sent=state.payroll.deliveries.some(d=>d.item_id===item.id&&d.status==='sent');
  return `<div class="button-row payroll-actions">${period.status==='draft'?`<button class="icon-button" data-action="payroll-edit" data-id="${item.id}" aria-label="Revisar pago de ${escape(item.employee_snapshot.full_name)}">${icon('edit')}</button>`:''}<a class="btn small" href="/api/payslips/${item.id}.pdf" target="_blank" rel="noopener" aria-label="Ver colilla de ${escape(item.employee_snapshot.full_name)}" title="Ver colilla PDF">${icon('report')}PDF</a><button class="btn small" data-action="payslip-email" data-id="${item.id}" aria-label="${sent?'Reenviar':'Enviar'} colilla a ${escape(item.employee_snapshot.full_name)}" title="${period.status==='draft'?'Revisa el destinatario; primero debes cerrar la nómina':!state.data.smtp_configured?'Revisa el destinatario; falta configurar el correo de la empresa':'Enviar el PDF al correo del empleado'}">${icon('mail')}${sent?'Reenviar correo':'Enviar correo'}</button></div>`;
}
function payslipEmailForm(id) {
  const item=state.payroll.items.find(i=>i.id===id);
  const recipient=item.recipient_email||'';
  const sent=state.payroll.deliveries.some(d=>d.item_id===id&&d.status==='sent');
  const pending=[];
  if(state.payroll.period.status!=='closed')pending.push('Primero cierra la nómina para enviar una colilla con importes definitivos.');
  if(!state.data.smtp_configured)pending.push('El correo de la empresa aún no está configurado. Completa la configuración de correo en el servidor antes de enviar.');
  if(!recipient)pending.push('El trabajador necesita un correo electrónico en su perfil.');
  formModal(sent?'Reenviar colilla por correo':'Enviar colilla por correo','payslip-email',`<div class="field full"><div class="preview-card"><div class="section-title">${escape(item.employee_snapshot.full_name)}</div><div class="email-address"><span>De</span><strong>${escape(state.data.smtp_from||'contabilidad@circuitocinco.com')}</strong></div><div class="email-address"><span>Para</span><strong>${escape(recipient||'Sin correo registrado')}</strong></div><div class="figure-note">Destinatario tomado del correo actual del perfil del trabajador.</div></div></div><div class="field full"><div class="email-attachment">${icon('report')}<div><strong>Colilla de pago en PDF</strong><small>${civil(state.payroll.period.start_date)} al ${civil(state.payroll.period.end_date)}</small></div><a class="btn small" href="/api/payslips/${id}.pdf" target="_blank" rel="noopener">${icon('eye')}Revisar PDF</a></div></div>${pending.map(message=>`<div class="notice warning">${escape(message)}</div>`).join('')}${sent?'<div class="notice warning">Esta colilla ya fue aceptada por el servidor de correo. Confirma si deseas reenviarla.</div>':''}`,sent?'Reenviar correo':'Enviar correo',`data-id="${id}" data-recipient="${escape(recipient)}" data-resend="${sent}"`);
  const submit=modal.querySelector('[type="submit"]');
  submit.disabled=pending.length>0;
  submit.innerHTML=icon('mail')+escape(sent?'Reenviar correo':'Enviar correo');
}
function payrollPage() {
  const loaded=state.payroll;
  if (loaded) {
    const p=loaded.period,items=loaded.items,total=items.reduce((s,i)=>s+Number(i.net_cents),0),reviewed=items.filter(i=>i.reviewed).length;
    return `${heading(periodLabel(p),`${civil(p.start_date)} al ${civil(p.end_date)} · ${reviewed} de ${items.length} trabajadores revisados`,btn('Todos los periodos','payroll-back','arrow'),'NÓMINA QUINCENAL')}<div class="stats">${stat('Trabajadores',items.length,'Personas incluidas en el periodo','people')}${stat('Ingresos',money(items.reduce((s,i)=>s+Number(i.gross_cents),0)),'Salario quincenal más comisiones','wallet','money')}${stat('Deducciones',money(items.reduce((s,i)=>s+Number(i.deductions_cents),0)),'Caja, renta, préstamos y otros','report','money')}${stat('Total neto',money(total),'Importe total a pagar','check','money')}</div><div class="notice ${p.status==='draft'?'warning':''}"><strong>${p.status==='draft'?'Nómina en preparación.':'Nómina cerrada.'}</strong> ${p.status==='draft'?'Revisa y guarda cada trabajador. Los ajustes por ingreso o salida durante la quincena necesitan un motivo.':'Los importes y datos de las colillas se conservan como estaban al cerrar este periodo.'}</div><section class="panel"><div class="toolbar"><div class="button-row">${tag(p.status==='draft'?'Borrador':'Cerrada',p.status==='draft'?'amber':'')}<span class="muted small">Importes en colones</span></div><div class="button-row">${btn('Exportar CSV','payroll-csv','download','small')}${p.status==='draft'?btn('Actualizar plantilla','payroll-sync','refresh','small')+btn('Cerrar nómina','payroll-close','lock','primary small'):''}</div></div><div class="table-wrap"><table><thead><tr><th>Trabajador</th><th>Salario quincenal</th><th>Comisiones</th><th>Deducciones</th><th>Neto</th><th>Revisión</th><th>Acciones</th></tr></thead><tbody>${items.map(i=>{const partial=i.employee_snapshot.hire_date>p.start_date||(i.employee_snapshot.termination_date&&i.employee_snapshot.termination_date<p.end_date);const delivered=loaded.deliveries.find(d=>d.item_id===i.id);return `<tr><td>${person(i.employee_snapshot)}${partial?'<div class="figure-note negative">Ingreso o salida durante el periodo</div>':''}</td><td class="no-wrap">${money(i.base_cents)}</td><td>${money(i.commissions_cents)}</td><td>${money(i.deductions_cents)}</td><td><strong class="no-wrap">${money(i.net_cents)}</strong></td><td>${tag(i.reviewed?'Revisado':'Pendiente',i.reviewed?'':'amber')}${delivered?`<div class="figure-note ${delivered.status==='failed'?'negative':''}">${delivered.status==='sent'?'Correo aceptado':delivered.status==='sending'?'Enviando correo':'Error de correo'}</div>`:''}</td><td>${payslipActions(i,p)}</td></tr>`;}).join('')}</tbody></table></div></section>${!state.data.smtp_configured?'<p class="figure-note">El envío de colillas se habilita al configurar SMTP en el servidor. Ya puedes consultar y descargar los PDF.</p>':''}`;
  }
  return `${heading('Cada quincena, en orden','Salarios base, comisiones y deducciones en un periodo que puedes revisar.',btn('Nueva quincena','payroll-new','plus','primary'))}<section class="panel"><div class="panel-header"><div><h2>Periodos de pago</h2><p>Primera quincena: 1–15 · segunda: 16–fin de mes</p></div>${icon('wallet')}</div>${state.data.periods.length?`<div class="table-wrap"><table><thead><tr><th>Periodo</th><th>Fechas</th><th>Trabajadores</th><th>Neto total</th><th>Estado</th><th></th></tr></thead><tbody>${state.data.periods.map(p=>`<tr><td><strong>${escape(periodLabel(p))}</strong></td><td>${civil(p.start_date,{day:'numeric',month:'short'})} — ${civil(p.end_date,{day:'numeric',month:'short'})}</td><td>${p.employee_count}</td><td>${money(p.total_net_cents)}</td><td>${tag(p.status==='closed'?'Cerrada':'Borrador',p.status==='closed'?'':'amber')}</td><td>${btn('Abrir','payroll-open','arrow','small',`data-id="${p.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('Prepara tu primera quincena','El salario mensual se divide entre dos. Luego puedes ingresar comisiones, rebajos y ajustes por trabajador.',btn('Crear periodo de pago','payroll-new','plus','primary'),'wallet')}</section>`;
}
function reportsPage() {
  const year=state.reportYear||state.data.today.slice(0,4),asOf=state.reportDate||state.data.today,r=state.report;
  return `${heading('Información para decidir','Consulta saldos y los días de vacaciones registrados durante el año.',btn('Exportar CSV','report-csv','download','primary',r?'':'disabled'))}<section class="panel"><form data-form="report" class="toolbar"><div class="report-tools">${field('Año de movimientos','year',year,'number','required min="1900" max="2200"')}${field('Fecha del saldo','as_of',asOf,'date','required')}${btn('Consultar','report-submit','search','primary small','type="submit"')}</div><span class="small muted">Días de vacaciones · todos los trabajadores</span></form><div id="report-results">${r?reportTable(r):empty('Consulta los saldos de tu equipo','Selecciona el año y la fecha para generar el reporte.','','report')}</div><div class="report-note">El ajuste histórico conserva el total descontado, pero no las fechas anteriores al corte. Los días disfrutados del año incluyen únicamente movimientos registrados con fecha, hasta la fecha consultada. El saldo se calcula con el historial y los datos actuales; no constituye una fotografía de cambios anteriores.</div></section>`;
}
function reportTable(r) {
  if (!r.employees.length) return empty('Todavía no hay trabajadores','Registra los perfiles para consultar sus saldos.','','people');
  return `<div class="table-wrap"><table><thead><tr><th>Trabajador</th><th>Estado</th><th>Acumulado</th><th>Ajuste histórico</th><th>Disfrutado total</th><th>Reservado</th><th>Disponible</th><th>Disfrutado en ${r.year}</th><th></th></tr></thead><tbody>${r.employees.map(e=>`<tr><td>${person(e)}</td><td>${tag(e.active?'Activo':'Inactivo',e.active?'':'gray')}</td><td>${days(e.vacation.accrued)}</td><td>${days(e.vacation.historical)}<div class="figure-note">${e.historical_cutoff?civil(e.historical_cutoff):'Sin ajuste'}</div></td><td>${days(e.vacation.used)}</td><td>${days(e.vacation.reserved)}</td><td><strong class="${e.vacation.available<0?'negative':''}">${days(e.vacation.available)}</strong></td><td>${days(e.used_year)}${e.historical_detail_missing?'<div class="figure-note">Histórico sin fechas anteriores</div>':''}</td><td>${btn('Fechas','report-dates','calendar','small',`data-id="${e.id}"`)}</td></tr>`).join('')}</tbody></table></div>`;
}
function settingsPage() {
  const c=state.data.company;
  return `${heading('Tu espacio de trabajo','Datos de la empresa, cuentas de administrador e historial de cambios.',btn('Mi contraseña','password','lock'))}<div class="settings-grid"><section class="panel"><div class="panel-header"><div><h2>Datos de la empresa</h2><p>Se incluyen en las colillas de pago</p></div>${icon('settings')}</div><div class="panel-body"><form data-form="company">${field('Nombre de la empresa','name',c.name,'text','required maxlength="200"')}${field('Cédula jurídica','legal_id',c.legal_id,'text','maxlength="50"')}${field('Correo de la empresa','email',c.email,'email','maxlength="254"')}<div class="form-error" role="alert"></div><button class="btn primary" type="submit">${icon('check')}Guardar datos</button></form><div class="separator"></div><div class="section-title">Envío de colillas</div>${tag(state.data.smtp_configured?'Correo configurado':'Pendiente de configurar',state.data.smtp_configured?'':'amber')}<p class="figure-note">El remitente y la conexión de correo se configuran en el servidor. El historial indica si el servidor de correo aceptó cada envío.</p></div></section><section class="panel"><div class="panel-header"><div><h2>Cuentas de administrador</h2><p>Cada persona tiene su propio acceso</p></div>${btn('Nueva cuenta','user-new','plus','small')}</div><div class="table-wrap"><table><thead><tr><th>Administrador</th><th>Estado</th><th></th></tr></thead><tbody>${state.data.users.map(u=>`<tr><td><strong>${escape(u.name)}</strong><div class="figure-note">${escape(u.email)}</div>${u.must_change_password?'<div class="figure-note">Contraseña temporal</div>':''}</td><td>${tag(u.active?'Activa':'Desactivada',u.active?'':'gray')}</td><td>${u.id===state.user.id?tag('Tu cuenta','gray'):`<div class="button-row"><button class="icon-button" data-action="user-reset" data-id="${u.id}" aria-label="Restablecer contraseña de ${escape(u.name)}">${icon('lock')}</button>${btn(u.active?'Desactivar':'Activar','user-toggle',null,'small',`data-id="${u.id}"`)}</div>`}</td></tr>`).join('')}</tbody></table></div><div class="report-note">El acceso de empleados se incorporará en una etapa posterior. Los perfiles registrados todavía no tienen una cuenta de acceso.</div></section></div><section class="panel spacer-top"><div class="panel-header"><div><h2>Historial de cambios</h2><p>Los últimos 100 movimientos de la empresa</p></div>${icon('shield')}</div><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Administrador</th><th>Acción</th><th>Registro</th><th></th></tr></thead><tbody>${state.data.audit.map(a=>`<tr><td class="no-wrap">${timestamp(a.created_at)}</td><td>${escape(a.actor_name||'Sistema')}</td><td>${escape(a.action.replaceAll('_',' '))}</td><td>${escape(a.entity.replaceAll('_',' '))}</td><td>${btn('Detalle','audit-view','eye','small',`data-id="${a.id}"`)}</td></tr>`).join('')}</tbody></table></div></section>`;
}
function page() {return ({dashboard,employees:employeesPage,vacations:vacationsPage,holidays:holidaysPage,payroll:payrollPage,reports:reportsPage,settings:settingsPage})[state.tab]();}
function openModal(title,content,footer='') {
  modal.innerHTML=`<div class="modal-header"><h2 id="modal-title">${escape(title)}</h2><button class="icon-button" data-action="modal-close" aria-label="Cerrar ventana">${icon('close')}</button></div>${content}${footer}`;
  if (!modal.open) modal.showModal();
}
function formModal(title,form,content,submit='Guardar',extra='') {
  openModal(title,`<form data-form="${form}" ${extra}><div class="modal-body"><div class="form-grid">${content}<div class="form-error" role="alert"></div></div></div><div class="modal-footer"><button type="button" class="btn" data-action="modal-close">Cancelar</button><button class="btn primary" type="submit">${icon('check')}${escape(submit)}</button></div></form>`);
}
async function employeeForm(employee=null) {
  const e=employee||{active:true,historical_days:0,monthly_salary_cents:0,code:(await api('/employees/next-code')).code};
  formModal(e.id?'Editar perfil':'Nuevo empleado','employee',`<div class="form-section">Datos del trabajador</div>${field('Nombre completo','full_name',e.full_name,'text','required maxlength="200" data-full')}${field('Código interno','code',e.code,'text','required maxlength="30"', 'Sugerido automáticamente. Puedes cambiarlo antes de guardar.')}${field('Cédula','national_id',e.national_id,'text','required maxlength="40"')}${field('Correo electrónico','email',e.email,'email','required maxlength="254"')}${field('Teléfono','phone',e.phone,'tel','maxlength="40"')}${field('Fecha de nacimiento','birth_date',e.birth_date,'date',`required max="${state.data.today}"`)}${field('Fecha de ingreso','hire_date',e.hire_date,'date','required')}${field('Puesto','position',e.position,'text','maxlength="200"')}${field('Departamento','department',e.department,'text','maxlength="200"')}<div class="form-section">Salario y estado</div>${field('Salario base mensual (₡)','monthly_salary',e.id?Number(e.monthly_salary_cents)/100:'','number','required min="0" max="9999999999.99" step="0.01"','Cada quincena completa equivale a la mitad.')}${select('Estado','active',[[true,'Activo'],[false,'Inactivo']],e.active)}${field('Fecha de salida','termination_date',e.termination_date,'date','data-full','Solo para empleados inactivos. La acumulación se detiene en esta fecha.')}<div class="form-section">Vacaciones históricas</div>${field('Días históricos a descontar','historical_days',e.historical_days,'number','required min="0" max="100000" step="0.5"','Total utilizado hasta la fecha de corte.')}${field('Fecha de corte','historical_cutoff',e.historical_cutoff,'date',`max="${state.data.today}"`,'Los movimientos nuevos deben ser posteriores al corte.')}${textarea('Motivo o referencia del ajuste histórico','historical_note',e.historical_note,'Obligatorio si se descuentan días históricos. No reemplaza las fechas de vacaciones tomadas.')}${textarea('Observaciones','notes',e.notes)}`,e.id?'Guardar cambios':'Crear empleado',e.id?`data-id="${e.id}" data-revision="${e.revision}"`:'');
  if (!e.id) modal.querySelector('form').dataset.suggestedCode=e.code;
}
function employeeView(id) {
  const e=state.data.employees.find(e=>e.id===id),v=e.vacation;
  const records=state.data.vacations.filter(v=>v.employee_id===id);
  openModal('Perfil del trabajador',`<div class="modal-body"><div class="detail-header"><span class="avatar">${escape(initials(e.full_name))}</span><div><h3>${escape(e.full_name)}</h3><span class="muted small">${escape(e.position||'Puesto sin especificar')} · ${escape(e.code)}</span></div></div><div class="detail-grid">${[['Cédula',e.national_id],['Correo',e.email],['Estado',e.active?'Activo':'Inactivo'],['Ingreso',civil(e.hire_date)],['Nacimiento',civil(e.birth_date)],['Departamento',e.department||'—'],['Salario mensual',money(e.monthly_salary_cents)],['Base por quincena',money(Math.round(Number(e.monthly_salary_cents)/2))],['Teléfono',e.phone||'—']].map(([label,value])=>`<div class="detail-cell"><small>${escape(label)}</small><strong>${escape(value)}</strong></div>`).join('')}</div><div class="section-title">Vacaciones al ${civil(state.data.today)}</div><div class="preview-card"><div class="summary-row"><span>Acumulado · ${v.months} meses completos</span><strong>${days(v.accrued)} días</strong></div><div class="summary-row"><span>Descuento histórico</span><strong>${days(v.historical)} días</strong></div><div class="summary-row"><span>Días utilizados registrados</span><strong>${days(v.used)} días</strong></div><div class="summary-row"><span>Días reservados</span><strong>${days(v.reserved)} días</strong></div><div class="summary-row"><strong>Disponible para solicitar</strong><strong class="${v.available<0?'negative':''}">${days(v.available)} días</strong></div></div>${e.historical_cutoff?`<p class="figure-note">Corte histórico: ${civil(e.historical_cutoff)}. ${escape(e.historical_note)}</p>`:''}${v.available<0?'<div class="notice error spacer-top">Este trabajador tiene un saldo de vacaciones negativo.</div>':''}${e.termination_date?`<p class="figure-note">Salida: ${civil(e.termination_date)}</p>`:''}${e.notes?`<p class="figure-note">${escape(e.notes)}</p>`:''}<div class="section-title">Movimientos de vacaciones</div>${records.length?records.map(r=>`<div class="summary-row"><span>${civil(r.start_date)} — ${civil(r.end_date)}<div class="figure-note">${r.status==='cancelled'?'Cancelada':r.end_date<state.data.today?'Disfrutada':'Aprobada'}</div></span><strong>${days(r.days)} días</strong></div>`).join(''):'<p class="muted small">Todavía no hay movimientos registrados.</p>'}</div>`,`<div class="modal-footer">${e.active?btn('Registrar vacaciones','vacation-new','calendar','',`data-id="${e.id}"`):''}${btn('Editar perfil','employee-edit','edit','primary',`data-id="${e.id}"`)}</div>`);
}
function vacationForm(id='') {
  const employees=state.data.employees.filter(e=>e.active);
  if (!employees.length) return toast('Primero registre un trabajador activo.',true);
  state.preview=null;
  formModal('Registrar vacaciones','vacation',`${select('Trabajador','employee_id',employees.map(e=>[e.id,e.full_name]),id||employees[0].id,'required')}${select('Duración','half_day',[[false,'Días completos'],[true,'Medio día']],false)}${field('Desde (incluido)','start_date','','date','required')}${field('Hasta (incluido)','end_date','','date','required')}${textarea('Observación','note')}<div class="field full">${btn('Calcular días y revisar saldo','vacation-preview','calendar','','type="button"')}<div id="vacation-preview" class="spacer-top"></div></div>`,'Aprobar vacaciones');
}
function previewHtml(p) {return `<div class="preview-card"><div class="summary-row"><span>Días laborales a descontar</span><strong>${days(p.days)} días</strong></div><div class="summary-row"><span>Disponible antes del movimiento</span><strong>${days(p.before.available)} días</strong></div><div class="summary-row"><span>Disponible después del movimiento</span><strong class="${p.after.available<0?'negative':''}">${days(p.after.available)} días</strong></div></div><div class="preview-list">${p.entries.map(d=>`<span class="preview-day ${d.reason?'excluded':''}" title="${escape(d.reason||'Día laboral')}">${civil(d.date,{day:'numeric',month:'short'})}${d.days===0.5?' · ½':''}</span>`).join('')}</div>${p.after.available<0?'<div class="notice error"><strong>El trabajador quedará con saldo negativo.</strong><label class="check-label checkbox-note"><input type="checkbox" name="allow_negative">Confirmo el adelanto de vacaciones y el saldo negativo.</label></div>':''}<p class="figure-note">Las fechas tachadas no se descuentan. El saldo se vuelve a comprobar al aprobar.</p>`;}
function payrollForm(item) {
  const p=state.payroll.period,e=item.employee_snapshot,partial=e.hire_date>p.start_date||(e.termination_date&&e.termination_date<p.end_date);
  formModal(`Revisar pago · ${e.full_name}`,'payroll-item',`${partial?'<div class="notice warning">Ingreso o salida durante esta quincena. Registre manualmente el salario correspondiente y explique el importe revisado.</div>':''}<div class="notice">Salario mensual actual: <strong>${money(state.data.employees.find(x=>x.id===item.employee_id).monthly_salary_cents)}</strong>. La base automática se calcula al guardar.</div>${field('Salario quincenal ajustado (₡)','base_override',Number(item.base_cents)!==Number(item.automatic_cents)?Number(item.base_cents)/100:'','number','min="0" step="0.01"',`Vacío: usar salario mensual ÷ 2. Base guardada: ${money(item.automatic_cents)}.`)}${field('Comisiones (₡)','commissions',Number(item.commissions_cents)/100,'number','required min="0" step="0.01"')}${textarea('Motivo del salario revisado o ajustado','adjustment_reason',item.adjustment_reason,partial?'Obligatorio por ingreso o salida en este periodo.':'Obligatorio cuando cambia el importe automático.')}<div class="form-section">Deducciones de esta quincena</div>${field('Caja (₡)','caja',Number(item.caja_cents)/100,'number','required min="0" step="0.01"')}${field('Renta (₡)','renta',Number(item.renta_cents)/100,'number','required min="0" step="0.01"')}${field('Préstamos (₡)','loan',Number(item.loan_cents)/100,'number','required min="0" step="0.01"')}${field('Otras deducciones (₡)','other',Number(item.other_cents)/100,'number','required min="0" step="0.01"')}${textarea('Detalle de otras deducciones','other_reason',item.other_reason,'Obligatorio si hay otras deducciones.')}<div class="field full"><div class="summary-total"><span>Neto estimado de la quincena</span><strong id="payroll-net">${money(item.net_cents)}</strong></div></div>`,'Guardar como revisado',`data-id="${item.id}" data-revision="${item.revision}"`);
}
function payload(form) {return Object.fromEntries(new FormData(form).entries());}
async function openPayroll(id) {state.payroll=await api(`/payroll/${id}`);state.tab='payroll';render();}
function csv(filename,rows) {
  const cell = value => {let text=String(value??'');if (/^[=+\-@\t\r]/.test(text)) text="'"+text;return '"'+text.replaceAll('"','""')+'"';};
  const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'});
  const url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=filename;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
async function action(button) {
  const id=button.dataset.id;
  switch(button.dataset.action) {
    case 'navigate':state.tab=button.dataset.tab;state.search='';state.payroll=null;render();if(state.tab==='reports'&&!state.report){state.report=await api(`/reports/vacations?year=${state.data.today.slice(0,4)}&as_of=${state.data.today}`);render();}break;
    case 'menu':$('.sidebar').classList.toggle('open');break;
    case 'logout':await api('/auth/logout',{method:'POST',body:{}});state.user=null;state.data=null;renderAuth(true);break;
    case 'modal-close':if(state.user?.must_change_password){toast('Debe cambiar su contraseña temporal para continuar.',true);return;}modal.close();break;
    case 'employee-new':await employeeForm();break;
    case 'employee-edit':await employeeForm(state.data.employees.find(e=>e.id===id));break;
    case 'employee-view':employeeView(id);break;
    case 'vacation-new':vacationForm(id);break;
    case 'vacation-preview': {
      const form=button.closest('form');if(!form.reportValidity())return;
      const data=payload(form);data.half_day=data.half_day==='true';state.preview=await api('/vacations/preview',{method:'POST',body:data});$('#vacation-preview').innerHTML=previewHtml(state.preview);break;
    }
    case 'vacation-cancel':formModal('Cancelar movimiento de vacaciones','vacation-cancel',textarea('Motivo de cancelación','reason','','Los días se devolverán al saldo y el movimiento seguirá en el historial.'),'Cancelar vacaciones',`data-id="${id}"`);break;
    case 'holiday-new':formModal('Agregar feriado','holiday',field('Nombre del feriado','name','','text','required maxlength="200" data-full')+field('Fecha exacta','day','','date','required data-full'),'Agregar feriado');break;
    case 'holiday-delete': {const h=state.data.holidays.find(h=>h.id===id);formModal('Eliminar feriado','holiday-delete',`<div class="notice warning">¿Eliminar ${escape(h.name)} del ${civil(h.day)}? La fecha volverá a contarse como laboral si cae de lunes a viernes.</div>`,'Eliminar fecha',`data-id="${id}"`);break;}
    case 'payroll-new': {
      if(!state.data.employees.length)return toast('Registre los trabajadores antes de preparar una nómina.',true);
      const [year,month,day]=state.data.today.split('-').map(Number);
      formModal('Preparar una quincena','payroll-new',field('Año','year',year,'number','required min="2000" max="2200"')+select('Mes','month',Array.from({length:12},(_,i)=>[i+1,civil(`2026-${String(i+1).padStart(2,'0')}-01`,{month:'long'})]),month)+select('Quincena','half',[[1,'Primera · del 1 al 15'],[2,'Segunda · del 16 al fin de mes']],day<=15?1:2)+'<div class="notice">Se creará un borrador con los trabajadores que tengan relación laboral durante el periodo. Caja, renta y comisiones empezarán en cero para que revises cada importe.</div>','Crear borrador');break;
    }
    case 'payroll-open':await openPayroll(id);break;
    case 'payroll-back':state.payroll=null;render();break;
    case 'payroll-edit':payrollForm(state.payroll.items.find(i=>i.id===id));break;
    case 'payroll-sync':await api(`/payroll/${state.payroll.period.id}/sync`,{method:'POST',body:{}});await openPayroll(state.payroll.period.id);toast('Plantilla del borrador actualizada.');break;
    case 'payroll-close':formModal('Cerrar nómina','payroll-close',`<div class="notice warning">Al cerrar ${escape(periodLabel(state.payroll.period))}, los importes quedarán bloqueados. Revisa los pagos y las deducciones antes de continuar.</div><label class="check-label field full"><input type="checkbox" name="confirm" required>Confirmo que revisé los importes de todos los trabajadores.</label>`,'Cerrar y conservar importes');break;
    case 'payslip-email':payslipEmailForm(id);break;
    case 'payroll-csv':csv(`nomina-${state.payroll.period.start_date}.csv`,[['Código','Trabajador','Cédula','Salario mensual','Salario quincenal','Comisiones','Caja','Renta','Préstamos','Otros','Total deducciones','Salario neto','Motivo ajuste'],...state.payroll.items.map(i=>[i.employee_snapshot.code,i.employee_snapshot.full_name,i.employee_snapshot.national_id,...['monthly_salary_cents','base_cents','commissions_cents','caja_cents','renta_cents','loan_cents','other_cents','deductions_cents','net_cents'].map(k=>(Number(i[k])/100).toFixed(2)),i.adjustment_reason])]);break;
    case 'report-submit':button.closest('form').requestSubmit();break;
    case 'report-csv':if(state.report)csv(`vacaciones-${state.report.as_of}.csv`,[['Código','Trabajador','Cédula','Estado','Meses completos','Acumulado','Ajuste histórico','Fecha de corte','Disfrutado total','Saldo actual','Reservado','Disponible',`Disfrutado registrado ${state.report.year}`],...state.report.employees.map(e=>[e.code,e.full_name,e.national_id,e.active?'Activo':'Inactivo',e.vacation.months,e.vacation.accrued.toFixed(6),e.vacation.historical,e.historical_cutoff,e.vacation.used,e.vacation.balance.toFixed(6),e.vacation.reserved,e.vacation.available.toFixed(6),e.used_year])]);break;
    case 'report-dates': {const e=state.report.employees.find(e=>e.id===id),entries=state.data.vacations.filter(v=>v.employee_id===id&&v.status==='approved').flatMap(v=>v.entries).filter(d=>d.days>0&&Number(d.date.slice(0,4))===state.report.year&&d.date<=state.report.as_of).sort((a,b)=>a.date.localeCompare(b.date));openModal(`Vacaciones de ${e.full_name}`,`<div class="modal-body"><p class="muted small">Fechas registradas durante ${state.report.year}, hasta el ${civil(state.report.as_of)}.</p>${e.historical_detail_missing?'<div class="notice warning">Existe un ajuste histórico sin detalle de fechas. No está incluido en esta lista.</div>':''}${entries.length?entries.map(d=>`<div class="summary-row"><span>${civil(d.date,{weekday:'long',day:'numeric',month:'long'})}</span><strong>${days(d.days)} ${d.days===1?'día':'días'}</strong></div>`).join(''):empty('Sin fechas registradas','No hay días disfrutados con fecha en este periodo.','','calendar',true)}</div>`);break;}
    case 'user-new':formModal('Crear cuenta de administrador','user',field('Nombre','name','','text','required maxlength="200" data-full')+field('Correo de acceso','email','','email','required maxlength="254" data-full')+field('Contraseña temporal','password','','password','required minlength="12" maxlength="128" autocomplete="new-password" data-full','Entrega esta contraseña a la persona. Deberá cambiarla al ingresar.'),'Crear cuenta');break;
    case 'user-toggle': {const u=state.data.users.find(u=>u.id===id);formModal(u.active?'Desactivar cuenta':'Activar cuenta','user-toggle',`<div class="notice ${u.active?'warning':''}">${u.active?'Se cerrarán sus sesiones y se bloqueará el acceso de':'Se permitirá nuevamente el acceso de'} <strong>${escape(u.name)}</strong>. Se conservará su historial.</div>`,u.active?'Desactivar':'Activar',`data-id="${id}" data-active="${!u.active}"`);break;}
    case 'user-reset':formModal('Restablecer contraseña','user-reset',field('Nueva contraseña temporal','password','','password','required minlength="12" maxlength="128" autocomplete="new-password" data-full','Se cerrarán las sesiones existentes. La persona deberá cambiar esta contraseña al ingresar.'),'Restablecer contraseña',`data-id="${id}"`);break;
    case 'password':formModal('Cambiar mi contraseña','password',field('Contraseña actual','current_password','','password','required autocomplete="current-password" data-full')+field('Nueva contraseña','password','','password','required minlength="12" maxlength="128" autocomplete="new-password" data-full')+field('Confirma la nueva contraseña','password_confirm','','password','required minlength="12" maxlength="128" autocomplete="new-password" data-full'),'Cambiar contraseña');break;
    case 'audit-view': {const a=state.data.audit.find(a=>String(a.id)===id);openModal('Detalle del historial',`<div class="modal-body"><p class="muted small">${escape(a.actor_name)} · ${timestamp(a.created_at)}</p><div class="section-title">Antes</div><pre class="audit-detail">${escape(JSON.stringify(a.before_data,null,2)||'Sin registro anterior')}</pre><div class="section-title">Después</div><pre class="audit-detail">${escape(JSON.stringify(a.after_data,null,2)||'Sin información adicional')}</pre></div>`);break;}
  }
}
document.addEventListener('click',async event=> {
  const button=event.target.closest('[data-action]');if(!button||button.disabled)return;
  if(button.dataset.action==='report-submit')return; // submit nativo, sin solicitudes duplicadas
  if(button.tagName==='BUTTON'&&button.type!=='submit')event.preventDefault();
  const form=button.closest('form');const error=form?.querySelector('.form-error');if(error)error.textContent='';
  button.disabled=true;
  try{await action(button);}catch(e){if(error)error.textContent=e.message;else toast(e.message,true);}finally{button.disabled=false;}
});
document.addEventListener('submit',async event=> {
  const form=event.target;if(!form.dataset.form)return;event.preventDefault();
  if(form.dataset.busy)return;form.dataset.busy='true';
  const error=form.querySelector('.form-error'),submit=form.querySelector('[type="submit"]'),wasDisabled=submit?.disabled;if(error)error.textContent='';if(submit)submit.disabled=true;
  const data=payload(form);
  try {
    switch(form.dataset.form) {
      case 'login':case 'setup': {
        if(form.dataset.form==='setup'&&data.password!==data.password_confirm)throw new Error('Las contraseñas no coinciden.');
        const result=await api(`/auth/${form.dataset.form}`,{method:'POST',body:data});state.user=result.user;state.csrf=result.csrf;
        if(state.user.must_change_password) {app.innerHTML='<div class="loading-screen"><img class="loading-logo" src="/assets/circuito-cinco-logo.png" alt="Circuito Cinco" width="1495" height="381"><p>Cambia tu contraseña temporal para continuar.</p></div>';action({dataset:{action:'password'}});}
        else await load();break;
      }
      case 'employee': {
        data.active=data.active==='true';data.revision=Number(form.dataset.revision);
        data.use_suggested_code=!form.dataset.id && data.code.trim()===form.dataset.suggestedCode;
        const saved=await api(form.dataset.id?`/employees/${form.dataset.id}`:'/employees',{method:form.dataset.id?'PUT':'POST',body:data});
        modal.close();await load();toast(`Perfil del trabajador guardado con código ${saved.code}.`);break;
      }
      case 'vacation':data.half_day=data.half_day==='true';data.allow_negative=data.allow_negative==='on';if(!state.preview)throw new Error('Calcula los días y revisa el saldo antes de aprobar.');if(state.preview.after.available<0&&!data.allow_negative)throw new Error('Confirme expresamente el adelanto de vacaciones y el saldo negativo.');await api('/vacations',{method:'POST',body:data});modal.close();await load();toast('Vacaciones aprobadas y saldo actualizado.');break;
      case 'vacation-cancel':await api(`/vacations/${form.dataset.id}/cancel`,{method:'POST',body:data});modal.close();await load();toast('Movimiento cancelado. Los días se devolvieron al saldo.');break;
      case 'holiday':await api('/holidays',{method:'POST',body:data});modal.close();await load();toast('Feriado agregado al calendario.');break;
      case 'holiday-delete':await api(`/holidays/${form.dataset.id}`,{method:'DELETE',body:{}});modal.close();await load();toast('Feriado eliminado.');break;
      case 'payroll-new': {const p=await api('/payroll',{method:'POST',body:data});modal.close();await load();await openPayroll(p.id);toast('Borrador de quincena creado.');break;}
      case 'payroll-item':data.revision=Number(form.dataset.revision);await api(`/payroll/${state.payroll.period.id}/items/${form.dataset.id}`,{method:'PUT',body:data});modal.close();await openPayroll(state.payroll.period.id);toast('Pago revisado y guardado.');break;
      case 'payroll-close':await api(`/payroll/${state.payroll.period.id}/close`,{method:'POST',body:{}});modal.close();await load();await openPayroll(state.payroll.period.id);toast('Nómina cerrada. Las colillas están listas.');break;
      case 'payslip-email': {
        if(state.payroll.period.status!=='closed'||!state.data.smtp_configured)throw new Error('Cierra la nómina y configura el correo de la empresa antes de enviar.');
        await api(`/payslips/${form.dataset.id}/email`,{method:'POST',body:{recipient:form.dataset.recipient,resend:form.dataset.resend==='true'}});
        modal.close();await openPayroll(state.payroll.period.id);toast('El servidor de correo aceptó la colilla.');break;
      }
      case 'report':state.reportYear=data.year;state.reportDate=data.as_of;state.report=await api(`/reports/vacations?year=${encodeURIComponent(data.year)}&as_of=${encodeURIComponent(data.as_of)}`);render();break;
      case 'company':await api('/company',{method:'PUT',body:data});await load();toast('Datos de la empresa guardados.');break;
      case 'user':await api('/users',{method:'POST',body:data});modal.close();await load();toast('Cuenta de administrador creada.');break;
      case 'user-toggle':await api(`/users/${form.dataset.id}`,{method:'PATCH',body:{active:form.dataset.active==='true'}});modal.close();await load();toast('Estado de la cuenta actualizado.');break;
      case 'user-reset':await api(`/users/${form.dataset.id}`,{method:'PATCH',body:{active:state.data.users.find(u=>u.id===form.dataset.id).active,password:data.password}});modal.close();await load();toast('Contraseña temporal guardada.');break;
      case 'password':if(data.password!==data.password_confirm)throw new Error('Las contraseñas no coinciden.');{const result=await api('/auth/password',{method:'POST',body:data});state.csrf=result.csrf;state.user.must_change_password=false;modal.close();await load();toast('Tu contraseña fue actualizada.');}break;
    }
  }catch(e){if(error)error.textContent=e.message;else toast(e.message,true);if(form.dataset.form==='payslip-email'&&state.payroll){try{await openPayroll(state.payroll.period.id);}catch{}}}finally{delete form.dataset.busy;if(submit)submit.disabled=Boolean(wasDisabled);}
});
document.addEventListener('input',event=> {
  if(event.target.id==='employee-search'){state.search=event.target.value;$('#employee-table').innerHTML=employeeRows();}
  const form=event.target.closest('form');
  if(form?.dataset.form==='vacation'&&['employee_id','start_date','end_date','half_day'].includes(event.target.name)){state.preview=null;$('#vacation-preview').innerHTML='';}
  if(form?.dataset.form==='payroll-item') {
    const d=payload(form),i=state.payroll.items.find(i=>i.id===form.dataset.id),e=state.data.employees.find(e=>e.id===i.employee_id);
    const automatic=(state.payroll.period.half===2?Math.floor(Number(e.monthly_salary_cents)/2):Math.ceil(Number(e.monthly_salary_cents)/2))/100;
    const net=(d.base_override===''?automatic:Number(d.base_override))+Number(d.commissions||0)-['caja','renta','loan','other'].reduce((s,k)=>s+Number(d[k]||0),0);
    $('#payroll-net').textContent=money(Math.round(net*100));$('#payroll-net').classList.toggle('negative',net<0);
  }
});
document.addEventListener('change',event=> {
  if(event.target.id==='employee-filter'){state.filter=event.target.value;$('#employee-table').innerHTML=employeeRows();}
  if(event.target.id==='vacation-filter'){state.vacationFilter=event.target.value;render();}
});
modal.addEventListener('cancel',event=>{if(state.user?.must_change_password)event.preventDefault();});
async function init() {
  try {const auth=await api('/auth/status');state.user=auth.user;state.csrf=auth.csrf;
    if(!auth.user)renderAuth(auth.initialized);
    else if(auth.user.must_change_password){app.innerHTML='<div class="loading-screen"><img class="loading-logo" src="/assets/circuito-cinco-logo.png" alt="Circuito Cinco" width="1495" height="381"><p>Cambia tu contraseña temporal para continuar.</p></div>';await action({dataset:{action:'password'}});}
    else await load();
  }catch(e){app.innerHTML=`<div class="loading-screen"><img class="loading-logo" src="/assets/circuito-cinco-logo.png" alt="Circuito Cinco" width="1495" height="381"><strong>No pudimos conectar con la aplicación.</strong><p>${escape(e.message)}</p><p class="muted small">Comprueba que el servidor y PostgreSQL estén disponibles.</p><button class="btn primary" data-action="reload">Volver a intentar</button></div>`;$('#app [data-action="reload"]').addEventListener('click',()=>location.reload());}
}
await init();
